const items = $input.all();
const output = [];

for (let i = 0; i < items.length; i++) {
  const row = items[i].json;
  const appId = row["Application ID"];
  const status = (row["Status"] || '').trim();
  const alertSent = (row["Alert Sent"] || '').trim();

  // Ignore initial/default submission statuses (Pending, Submitted, جديد). Status changes like 'Under Review' or 'In Progress' MUST trigger alerts!
  const isInitialStatus = !status || status === "Pending" || status === "Submitted" || status === "جديد" || status === "قيد الانتظار";

  if (appId && !isInitialStatus && alertSent !== "Yes") {
    output.push({
      json: {
        rowNumber: i + 2, // Row index 0 is line 2
        appId,
        "Application ID": appId,
        serviceName: row["Service Name"],
        firstName: row["User First Name"],
        lastName: row["User Last Name"],
        whatsapp: row["User WhatsApp Number"],
        email: row["User Email"],
        status,
        modificationDetails: row["Admin Modification Request"] || row["Modification Details"] || "",
        trackingLink: row["Tracking Link"] || ""
      }
    });
  }
}
return output;

const items = $input.all();
const output = [];

for (let i = 0; i < items.length; i++) {
  const row = items[i].json.body || items[i].json;
  const status = (row.status || "").trim().toLowerCase();
  const email = String(row.email || row["User Email"] || "").toLowerCase();
  const whatsapp = String(row.whatsapp || row["User WhatsApp Number"] || "");
  const skipSms = row.skipSms === true || email.includes("example.com") || whatsapp.includes("000000");

  const isFinalDecision = status.includes("approv") || status.includes("reject") || status.includes("قبول") || status.includes("اعتماد") || status.includes("رفض");

  if (isFinalDecision && !skipSms) {
    output.push(items[i]);
  }
}

return output;

const items = $input.all();
const output = [];

for (let i = 0; i < items.length; i++) {
  const body = items[i].json.body || items[i].json;
  const status = (body.status || '').trim().toLowerCase();
  const isStatusUpdate = body.isStatusUpdate === true;
  const isNotInitial = status && status !== 'submitted' && status !== 'pending' && status !== 'جديد';
  const email = (body.email || '').toLowerCase();
  const whatsapp = (body.whatsapp || '');
  const skipSms = body.skipSms === true || isStatusUpdate || isNotInitial || email.includes('example.com') || whatsapp.includes('000000');

  if (!skipSms) {
    output.push(items[i]);
  }
}

return output;
